/// `AnimIds_Init` 0x15aec0: the lookup modes and the index tables written
pub fn init(m: &mut Mem) {
    for (c, &mode) in LOOKUP_MODES.iter().enumerate() {
        m.w32(crate::animctl::CLIP_TABLE + 0x1c * c as u32 + 4, mode as u32);
    }
    for &(at, words) in RUNS.iter() {
        for (k, &w) in words.iter().enumerate() {
            m.w32(at + 4 * k as u32, w);
        }
    }
    for &(at, h) in HALVES.iter() {
        m.w16(at, h);
    }
}
